package org.humanjourney.core.mapfeature;
import java.util.*;
import com.google.gson.*;
import org.humanjourney.core.geography.DiscoveryLedger;
import org.humanjourney.core.water.WaterGeography.Point;
public record MapFeature(View view,double discoveryRadius,int schemaVersion){
 public MapFeature(View view,double radius){this(view,radius,1);}
 public enum Type{OCEAN,SEA,GULF,BAY,STRAIT,LAKE,RIVER;public String label(){return name().charAt(0)+name().substring(1).toLowerCase(Locale.ROOT);}}
 /** Deliberately excludes discovery radius and every server gameplay/context field. */
 public record View(String id,String label,Type type,String dimension,int priority,FeatureGeometry geometry){public View{if(!DiscoveryLedger.validId(id)||label==null||label.isBlank()||label.length()>128||label.chars().anyMatch(Character::isISOControl)||type==null||dimension==null||dimension.length()>256||!dimension.matches("[a-z0-9_.-]+:[a-z0-9_./-]+")||Math.abs((long)priority)>1000000||geometry==null)throw new IllegalArgumentException("invalid feature metadata");}}
 public MapFeature{Objects.requireNonNull(view);if(schemaVersion!=1&&schemaVersion!=2)throw new IllegalArgumentException("unsupported feature schema");if(!Double.isFinite(discoveryRadius)||discoveryRadius<1||discoveryRadius>64)throw new IllegalArgumentException("discovery_radius must be finite 1..64");}
 private static void keys(JsonObject o,Set<String> allowed){for(String k:o.keySet())if(!allowed.contains(k))throw new IllegalArgumentException("unknown feature field: "+k);}
 private static String string(JsonObject o,String key){var e=o.get(key);if(e==null||!e.isJsonPrimitive()||!e.getAsJsonPrimitive().isString())throw new IllegalArgumentException("missing/invalid "+key);return e.getAsString();}
 private static double number(JsonObject o,String key,double fallback){if(!o.has(key))return fallback;var e=o.get(key);if(!e.isJsonPrimitive()||!e.getAsJsonPrimitive().isNumber())throw new IllegalArgumentException("invalid "+key);double v=e.getAsDouble();if(!Double.isFinite(v))throw new IllegalArgumentException("non-finite "+key);return v;}
 private static List<Point> points(JsonElement value,int maximum,String context){if(value==null||!value.isJsonArray()||value.getAsJsonArray().size()>maximum)throw new IllegalArgumentException(context+": invalid points/limit");var result=new ArrayList<Point>();for(var e:value.getAsJsonArray()){if(!e.isJsonArray()||e.getAsJsonArray().size()!=2)throw new IllegalArgumentException(context+": point must be [X,Z]");var p=e.getAsJsonArray();for(var n:p)if(!n.isJsonPrimitive()||!n.getAsJsonPrimitive().isNumber())throw new IllegalArgumentException(context+": non-numeric point");result.add(new Point(p.get(0).getAsDouble(),p.get(1).getAsDouble()));}return result;}
 private static final class Budget{int rings,vertices;void ring(JsonElement e,String context){if(e==null||!e.isJsonArray())throw new IllegalArgumentException(context+": ring must be point array");rings++;vertices+=e.getAsJsonArray().size();if(rings>FeatureGeometry.MAX_RINGS||vertices>FeatureGeometry.MAX_VERTICES)throw new IllegalArgumentException(context+": exceeds 128 rings/4096 vertices");}}
 private static FeatureGeometry.Ring ring(JsonElement e,Budget budget,String context){budget.ring(e,context);try{return new FeatureGeometry.Ring(points(e,FeatureGeometry.MAX_VERTICES,context));}catch(RuntimeException error){throw new IllegalArgumentException(context+": "+error.getMessage(),error);}}
 private static FeatureGeometry.Part part(JsonObject o,Budget budget,String context){keys(o,Set.of("outer","holes"));var outer=ring(o.get("outer"),budget,context+" outer");var holes=new ArrayList<FeatureGeometry.Ring>();if(o.has("holes")){if(!o.get("holes").isJsonArray()||o.getAsJsonArray("holes").size()>127)throw new IllegalArgumentException(context+": invalid holes/limit");int i=0;for(var h:o.getAsJsonArray("holes"))holes.add(ring(h,budget,context+" hole["+(i++)+"]"));}try{return new FeatureGeometry.Part(outer,holes);}catch(RuntimeException error){throw new IllegalArgumentException(context+": "+error.getMessage(),error);}}
 private static FeatureGeometry geometry(JsonObject g,int schema,String id){String kind=string(g,"type");if(schema==1){keys(g,Set.of("type","points"));if(!Set.of("polygon","polyline").contains(kind))throw new IllegalArgumentException("unsupported v1 geometry");return new FeatureGeometry(FeatureGeometry.Kind.valueOf(kind.toUpperCase(Locale.ROOT)),points(g.get("points"),512,id+" v1 path"),null);}if(kind.equals("polyline")){keys(g,Set.of("type","points"));return FeatureGeometry.polyline(points(g.get("points"),FeatureGeometry.MAX_VERTICES,id+" v2 polyline"));}var budget=new Budget();if(kind.equals("polygon")){keys(g,Set.of("type","outer","holes"));var body=g.deepCopy();body.remove("type");return FeatureGeometry.polygon(part(body,budget,id+" polygon"));}if(kind.equals("multipolygon")){keys(g,Set.of("type","polygons"));var values=g.getAsJsonArray("polygons");if(values==null||values.isEmpty()||values.size()>128)throw new IllegalArgumentException(id+": invalid polygon parts/limit");var parts=new ArrayList<FeatureGeometry.Part>();int i=0;for(var v:values){if(!v.isJsonObject())throw new IllegalArgumentException(id+": part must be object");parts.add(part(v.getAsJsonObject(),budget,id+" part["+(i++)+"]"));}return FeatureGeometry.multipolygon(parts);}throw new IllegalArgumentException(id+": unsupported v2 geometry");}
 public static MapFeature parse(JsonElement input){if(input==null||!input.isJsonObject())throw new IllegalArgumentException("feature must be object");var o=input.getAsJsonObject();keys(o,Set.of("schema_version","id","label","feature_type","dimension","priority","discovery_radius","geometry"));double version=number(o,"schema_version",-1);if(version!=1&&version!=2)throw new IllegalArgumentException("unsupported feature schema");String id=string(o,"id"),type=string(o,"feature_type");if(!type.matches("ocean|sea|gulf|bay|strait|lake|river"))throw new IllegalArgumentException("unsupported feature type");double priority=number(o,"priority",0);if(priority!=Math.rint(priority)||Math.abs(priority)>1000000)throw new IllegalArgumentException("invalid feature priority");var g=o.getAsJsonObject("geometry");if(g==null)throw new IllegalArgumentException("missing geometry");return new MapFeature(new View(id,string(o,"label"),Type.valueOf(type.toUpperCase(Locale.ROOT)),string(o,"dimension"),(int)priority,geometry(g,(int)version,id)),number(o,"discovery_radius",8),(int)version);}
}
